#include <bits/stdc++.h>
using namespace std;

#define FOR(i,st,ed) for(int i=st;i<=ed;++i)
#define FORD(i,st,ed) for(int i=st;i>=ed;--i)
typedef long long ll;

inline int read_int() {
    int x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-') {f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

inline ll read_ll() {
    ll x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-') {f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

const int MAXN=32,MOD=1000000007;

inline void add_mod(int &x,int y){
    x+=y;
    if(x>=MOD) x-=MOD;
}

struct Matrix {
    int a[MAXN][MAXN];
    void reset() {
        memset(a,0,sizeof(a));
    }
    void print() {
        for(int i=1;i<=n+1;++i){
            for(int j=1;j<=n+1;++j){
                printf("%d%c",a[i][j],j==n+1?'\n':' ');
            }
        }
        putchar('\n');
    }
    Matrix operator*(const Matrix &rhs) const {
        Matrix res; res.reset();
        for(int i=1;i<=n+1;++i)
            for(int j=1;j<=n+1;++j)
                for(int k=1;k<=n+1;++k)
                    add_mod(res.a[i][j],(long long)a[i][k]*rhs.a[k][j]%MOD);
        return res;
    }
};

int n;
Matrix E, A[MAXN], pre[MAXN], suf[MAXN], ans;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    ll m=read_ll(); n=read();
    E.reset();
    for(int i=1;i<=n;++i) E.a[i][i]=1;
    ans=E;
    for(int i=1;i<=n;++i){
        A[i]=E;
        A[i].a[i][i]=1;
    }
    pre[0]=suf[n+1]=E;
    for(;m; m/=n){
        ll u=m%n;
        if(u){
            ll s=0;
            for(ll v=m;v;v/=n) s=(s+v/n)%n;
            u=(s+u-1)%n+1;
            for(;u!=s;--u){
                if(u<=0) u+=n;
                ans=A[u]*ans;
            }
        }
        for(int i=1;i<=n;++i) pre[i]=pre[i-1]*A[i];
        for(int i=n;i>=1;--i) suf[i]=A[i]*suf[i+1];
        for(int i=1;i<=n;++i) A[i]=suf[i]*pre[i-1];
    }
    int num=1;
    for(int i=1;i<=n;++i) add_mod(num,ans.a[n+1][i]);
    printf("%d\n",num);
    return 0;
}
